const tabId = 248688717;

const sideEffectsData = await browserjs(tabId, () => {
  const sections = {};
  const headings = Array.from(document.querySelectorAll('h2, h3'));

  for (let i = 0; i < headings.length; i++) {
    const h = headings[i];
    const title = h.textContent.trim();
    if (
      title.includes('Serious side effects') ||
      title.includes('Other side effects') ||
      title.includes('More common') ||
      title.includes('Less common') ||
      title.includes('Rare') ||
      title.includes('Important warnings') ||
      title.includes('Nervous system') ||
      title.includes('General adverse events') ||
      title.includes('Psychiatric')
    ) {
      let content = '';
      let el = h.nextElementSibling;
      while (el && !['H2', 'H3'].includes(el.tagName)) {
        content += el.innerText + '\n';
        el = el.nextElementSibling;
      }
      sections[title] = content.trim();
    }
  }
  return sections;
});

